'use strict';

/* Ilustrações de cabeçalho/seções (Meta). */
const ART = {court:'data:image/webp;base64,',dunk:'data:image/webp;base64,',duel:'data:image/webp;base64,',dribble:'data:image/webp;base64,',boss:'data:image/webp;base64,',sneakers:'data:image/webp;base64,',champs:'data:image/webp;base64,'};
const pgimg = (eb, ti, key, pos) => `<div class="hero ph" style="${pos ? 'background-position:' + pos + ';' : ''}background-image:linear-gradient(180deg,rgba(7,20,41,.05),rgba(7,20,41,.85)),url(${ART[key] || key || ''})"><div class="hero-t"><small>${eb}</small><b>${ti}</b></div></div>`;
const sban = (src, cls) => src ? `<div class="sban ${cls || ''}"><img src="${src}" alt=""></div>` : '';
const facSrc = k => { const a = FAC_IMGS[k]; return a ? a[Math.max(0, fl(G, k) - 1)].src : ''; };
